const listProjectsByOrganization = `-- name: ListProjectsByOrganization :many
SELECT 
    p.id, p.name, p.slug, p.task_prefix, p.description, p.avatar, p.color,
    p.status, p.priority, p.visibility, p.start_date, p.end_date,
    p.workflow_id, p.workspace_id, p.created_at, p.updated_at, p.archive,
    w.name AS workspace_name, w.slug AS workspace_slug, w.organization_id,
    (SELECT count(*) FROM tasks t WHERE t.project_id = p.id AND t.is_archived = false) AS task_count,
    (SELECT count(*) FROM project_members pm WHERE pm.project_id = p.id) AS member_count
FROM projects p
JOIN workspaces w ON p.workspace_id = w.id
WHERE p.archive = false
  AND w.organization_id = $1
  AND ($2::uuid IS NULL OR p.workspace_id = $2)
  AND ($3::text IS NULL OR p.status::text = $3)
  AND ($4::text IS NULL OR p.priority::text = $4)
  AND ($5::text IS NULL OR p.name ILIKE '%' || $5 || '%' OR p.slug ILIKE '%' || $5 || '%')
  AND (
      $6::boolean = true
      OR p.visibility = 'PUBLIC'
      OR (p.visibility = 'INTERNAL' AND EXISTS (SELECT 1 FROM workspace_members wm WHERE wm.workspace_id = p.workspace_id AND wm.user_id = $7))
      OR EXISTS (SELECT 1 FROM project_members pm WHERE pm.project_id = p.id AND pm.user_id = $7)
  )
ORDER BY p.created_at DESC
LIMIT $9::int OFFSET $8::int
`

